// FirstEnabledTransition is Appendix D selectTransitions, the half only this
// document can answer: the first of state's own transitions, in document order,
// that event enables and whose guard holds. The engine walks the atomic states
// and their ancestors and keeps the ordered set; the null event asks for
// eventless transitions.
//line helper.scxml:6
func (p *HelperPolicy) FirstEnabledTransition(state HelperState, event HelperEvent, engine *sce.Engine[HelperState, HelperEvent]) (sce.EnabledTransition[HelperState, sce.HistoryID], bool) {
	switch state {
	case HelperStateListening:
		if event == HelperEventSceTestSnapshot {
			// docs/SCE_TEST_PROFILE.md §12.3: a branch of the test component,
			// guarded by its cond and then its match on the round's snapshot.
			if p.sceTestContext.SnapshotPresent("ctl") {
				return sce.EnabledTransition[HelperState, sce.HistoryID]{
					Source:          state,
					Targets:         transitionTargetsOfHelper[state][0],
					TransitionIndex: 0,
					HasActions:      true,
					IsInternal:      false,
				}, true
			}
		}
	}
	return sce.EnabledTransition[HelperState, sce.HistoryID]{}, false
}

